#### 37\. 解数独
(https://leetcode.cn/problems/sudoku-solver/)
```cpp
class Solution {
public:
    int count = 0;
    using vuc = vector<unordered_set<char>>;
    void readSudoku(vector<vector<char>>& board, vuc& line, vuc& col,
                    vuc& box) {
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] != '.') {
                    count++;
                    char num = board[i][j];
                    int k = (i / 3) * 3 + (j / 3);
                    line[i].insert(num);
                    col[j].insert(num);
                    box[k].insert(num);
                }
            }
        }
    }
    bool traceBack(vector<vector<char>>& board, vuc& line, vuc& col, vuc& box) {
        if (count == 81)
            return true; // 终止条件
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == '.') {
                    int k = (i / 3) * 3 + (j / 3);
                    for (char m = '1'; m <= '9'; m++) {
                        if (line[i].count(m) || col[j].count(m) ||
                            box[k].count(m)) {
                            continue;
                        }
                        line[i].insert(m);
                        col[j].insert(m);
                        box[k].insert(m);
                        board[i][j] = m;
                        count++;
                        if (traceBack(board, line, col, box)) {
                            return true;
                        }
                        line[i].erase(m);
                        col[j].erase(m);
                        box[k].erase(m);
                        board[i][j] = '.';
                        count--;
                    }
                    return false;
                }
            }
        }
        return false;
    }
public:
    vector<vector<char>> solveSudoku(vector<vector<char>>& board) {
        vuc line(9), col(9), box(9);
        readSudoku(board, line, col, box);
        traceBack(board, line, col, box);
        return board;
    }
};
```
-   哈希表最适合的场景是频繁地**查询**，在回溯这种枚举算法中，频繁修改（增删）哈希表会消耗大量时间
-   本体可以使用状态压缩方式，用三维 bitset 存储棋盘信息

